        for a in range(len(bars)):
            for b in range(a + 1, len(bars)):
                if bars[a][1] == bars[b][1]:
                    return bars[b][0] - bars[a][0]
        if bars:
            return bars[0][0] + 1
        if n < 3:
            return n
        other = w if axis == 0 else h
        errors = []
        for p in range(1, n // 2 + 1):
            error = 0
            for residue in range(p):
                for j in range(other):
                    vals = [grid[k][j] if axis == 0 else grid[j][k] for k in range(residue, n, p)]
                    error += len(vals) - Counter(vals).most_common(1)[0][1]
            errors.append((error, p))
        base = errors[0][0]
        best_error, best_p = min(errors)
        return best_p if base - best_error >= 3 else n

    out = [row[:] for row in grid]
    for axis in (0, 1):
        n = h if axis == 0 else w
        p = period_for(axis)
        if p >= n:
            continue
        other = w if axis == 0 else h
        template = {}
        for residue in range(p):
            for j in range(other):
                vals = [grid[k][j] if axis == 0 else grid[j][k] for k in range(residue, n, p)]
